def eq_1_C(K, N, S_0, T, d_1, d_2, r):
    """C = S_0 N(d_1) - K e^{-rT} N(d_2),

    Formula f6, page 1, section '1 The Black–Scholes model', equation (1). Returns the right-hand side (C = …).

    Variables:
        N: the standard normal distribution function
        r: the risk-free interest rate
    """
    return -K*N(d_2)*math.exp(-T*r) + S_0*N(d_1)


def eq_2_d_1(K, S_0, T, r, sigma):
    """d_1 = \\frac{\\ln(S_0/K) + (r + \\sigma^2/2)T}{\\sigma\\sqrt{T}}

    Formula f9, page 1, section '1 The Black–Scholes model', equation (2). Returns the right-hand side (d_1 = …).

    Variables:
        r: the risk-free interest rate
    """
    return (T*(r + (1/2)*sigma**2) + math.log(S_0/K))/(math.sqrt(T)*sigma)


def eq_3_d_2(T, d_1, sigma):
    """d_2 = d_1 - \\sigma\\sqrt{T}.

    Formula f10, page 1, section '1 The Black–Scholes model', equation (3). Returns the right-hand side (d_2 = …).
    """
    return -math.sqrt(T)*sigma + d_1


def eq_5_SR(mu_p, r_f, sigma_p):
    """SR = \\frac{\\mu_p - r_f}{\\sigma_p}.

    Formula f19, page 1, section '2 Risk and return', equation (5). Returns the right-hand side (SR = …).

    Variables:
        r_f: the risk-free rate
    """
    return (mu_p - r_f)/sigma_p


def eq_6_PV(F, c, n, y):
    """PV = \\sum_{k=1}^n \\frac{c}{(1+y)^k} + \\frac{F}{(1+y)^n}.

    Formula f28, page 2, section '3 Discounting', equation (6). Returns the right-hand side (PV = …).

    Variables:
        c: coupon
    """
    return F*(y + 1)**(-n) + (builtins.sum(c*(y + 1)**(-k) for k in range(1, n+1)))

